1	// This file implements lossless archiving of one organization's audit
2	// export. AuditExport hands back detached in-memory records and the caller
3	// separately retains the checkpoint pinning them; an archive serializes the
4	// export so it can be saved to a file when the service instance ends and
5	// read back later, still paired with the caller's own checkpoint and still
6	// usable as the material for RecheckDecisionOffline.
7	//
8	// The format is a length-delimited binary encoding built by hand rather
9	// than encoding/json: JSON text cannot carry bytes that are not valid
10	// UTF-8 without silently replacing them with U+FFFD, which would collapse
11	// genuinely different content (a lone 0xFF, a lone 0xFE and a real U+FFFD)
12	// onto identical records and change their fingerprints. Every string is
13	// written from its exact bytes with a length prefix, and nil slices,
14	// non-nil empty slices and absent payloads are each marked explicitly.
15	//
16	// Integrity never comes from trust in the file. A decode reconstructs the
17	// records and then runs the same whole-material VerifyAudit chain check
18	// against the checkpoint the caller supplies independently; the checkpoint
19	// embedded in the archive is informational only and never authoritative.
20	package darksafe
21	
22	import (
23		"bytes"
24		"crypto/sha256"
25		"encoding/binary"
26		"errors"
27		"fmt"
28	)
29	
30	// ErrInvalidArchive means archive bytes are not a recognizable, complete,
31	// untampered audit archive: a foreign/truncated/trailing-byte framing, a
32	// failed checksum, or content that does not decode. Content-level failures
33	// (missing or mismatched organization, missing, out-of-order or modified
34	// records, a mismatched checkpoint) keep using ErrMissingOrganization and
35	// ErrInvalidRange exactly as the other audit entry points do.
36	var ErrInvalidArchive = errors.New("darksafe: invalid audit archive")
37	
38	// Archive framing:
39	//
40	//	magic   = archiveMagic
41	//	u32 BE  = byte length of the payload that follows
42	//	payload = archivePayloadLen bytes
43	//	32 bytes = SHA-256 checksum of payload
44	//
45	// A second archive concatenated to a first is trailing material, not a
46	// second frame: a read consumes exactly one frame and rejects any byte
47	// beyond it.
48	const archiveMagic = "darksafe-audit-archive-v1\n"
49	
50	const (
51		archiveTagBoolFalse byte = 0
52		archiveTagBoolTrue  byte = 1
53		archiveTagNil       byte = 0
54		archiveTagPresent   byte = 1
55	)
56	
57	// archiveWriter appends length-delimited fields to a byte buffer.
58	type archiveWriter struct {
59		buf []byte
60		err error
61	}
62	
63	func (w *archiveWriter) raw(data []byte) {
64		w.buf = append(w.buf, data...)
65	}
66	
67	// u32 writes a non-negative int as a big-endian uint32.
68	func (w *archiveWriter) u32(v int) {
69		if v < 0 || uint64(v) > 0xffffffff {
70			w.err = fmt.Errorf("%w: length out of range: %d", ErrInvalidArchive, v)
71			return
72		}
73		var b [4]byte
74		binary.BigEndian.PutUint32(b[:], uint32(v))
75		w.buf = append(w.buf, b[:]...)
76	}
77	
78	func (w *archiveWriter) boolean(v bool) {
79		if v {
80			w.buf = append(w.buf, archiveTagBoolTrue)
81		} else {
82			w.buf = append(w.buf, archiveTagBoolFalse)
83		}
84	}
85	
86	// stringField writes a string from its exact memory bytes. Nothing is
87	// validated, replaced or normalized: a lone 0xFF reaches the output as
88	// itself and stays distinguishable from 0xFE and a genuine U+FFFD.
89	func (w *archiveWriter) stringField(s string) {
90		w.u32(len(s))
91		if w.err != nil {
92			return
93		}
94		w.buf = append(w.buf, s...)
95	}
96	
97	// stringList preserves the slice shape explicitly: nil is one marker, a
98	// non-nil list is a marker, a count and the raw strings.
99	func (w *archiveWriter) stringList(items []string) {
100		if items == nil {
101			w.buf = append(w.buf, archiveTagNil)
102			return
103		}
104		w.buf = append(w.buf, archiveTagPresent)
105		w.u32(len(items))
106		for _, s := range items {
107			w.stringField(s)
108		}
109	}
110	
111	// policy writes one Policy by walking the single policy field table, so the
112	// archive's field order is the fingerprint's order by construction. Even the
113	// fingerprint-optional ResourceID is always written here (empty included),
114	// so every field round trips on its own; its placement is fixed by the
115	// table and therefore cannot move a fingerprint boundary.
116	func (w *archiveWriter) policy(p Policy) {
117		for i := range policyFields {
118			f := &policyFields[i]
119			switch f.kind {
120			case policyFieldString, policyFieldOptionalString:
121				w.stringField(f.getString(p))
122			case policyFieldBool:
123				w.boolean(f.getBool(p))
124			}
125		}
126	}
127	
128	func (w *archiveWriter) policyList(policies []Policy) {
129		if policies == nil {
130			w.buf = append(w.buf, archiveTagNil)
131			return
132		}
133		w.buf = append(w.buf, archiveTagPresent)
134		w.u32(len(policies))
135		for _, p := range policies {
136			w.policy(p)
137		}
138	}
139	
140	// change writes the policy-change payload, or a single absence marker:
141	// VerifyAudit only ever accepts a change payload on a policy-change record
142	// and its absence otherwise, but the distinction is encoded explicitly so
143	// decode never has to reconstruct a shape.
144	func (w *archiveWriter) change(c *PolicyChange) {
145		if c == nil {
146			w.buf = append(w.buf, archiveTagNil)
147			return
148		}
149		w.buf = append(w.buf, archiveTagPresent)
150		w.u32(c.Version)
151		w.policyList(c.Policies)
152		w.u32(c.SourceVersion)
153		w.boolean(c.RolledBack)
154	}
155	
156	func (w *archiveWriter) subject(su Subject) {
157		w.stringField(su.ID)
158		w.stringField(su.Kind)
159		w.stringList(su.Roles)
160		w.boolean(su.Disabled)
161	}
162	
163	func (w *archiveWriter) resource(r Resource) {
164		w.stringField(r.ID)
165		w.stringField(r.Scope)
166	}
167	
168	func (w *archiveWriter) decision(d Decision) {
169		w.boolean(d.Allowed)
170		w.stringField(d.Reason)
171		w.stringList(d.Matched)
172		w.u32(d.Version)
173	}
174	
175	func (w *archiveWriter) decisionRecord(d *DecisionRecord) {
176		if d == nil {
177			w.buf = append(w.buf, archiveTagNil)
178			return
179		}
180		w.buf = append(w.buf, archiveTagPresent)
181		w.stringField(d.Request.SubjectOrg)
182		w.stringField(d.Request.ResourceOrg)
183		w.subject(d.Request.Subject)
184		w.resource(d.Request.Resource)
185		w.stringField(d.Request.Action)
186		w.decision(d.Decision)
187	}
188	
189	// EncodeAuditArchive serializes one complete audit export into savable
190	// bytes. org is the organization name, records is its complete chain from
191	// sequence 1 (a valid prefix ending at some historical sequence is enough,
192	// provided cp pins exactly that sequence), and cp is the checkpoint the
193	// caller separately retains. An organization with no records archives too:
194	// records is empty and cp is its sequence-0 genesis checkpoint.
195	//
196	// The whole material is validated exactly as VerifyAudit would before any
197	// bytes are returned: a missing organization is ErrMissingOrganization, and
198	// a missing, out-of-order or foreign record, modified content or checkpoint
199	// mismatch is ErrInvalidRange. On failure no archive bytes are returned.
200	// The checkpoint is carried in the archive for reference, but never stands
201	// in for the separately retained evidence: DecodeAuditArchive always
202	// validates against the checkpoint handed to it. The call is read-only:
203	// neither the records nor any service state are mutated and no audit record
204	// is appended.
205	func EncodeAuditArchive(org string, records []AuditRecord, cp Checkpoint) ([]byte, error) {
206		if org == "" {
207			return nil, ErrMissingOrganization
208		}
209		if err := VerifyAudit(org, records, cp); err != nil {
210			return nil, err
211		}
212	
213		pw := &archiveWriter{}
214		pw.stringField(org)
215		pw.u32(cp.EndSeq)
216		pw.stringField(cp.Fingerprint)
217		pw.u32(len(records))
218		for i := range records {
219			r := &records[i]
220			pw.stringField(r.Org)
221			pw.u32(r.Seq)
222			pw.stringField(r.Kind)
223			pw.change(r.Change)
224			pw.decisionRecord(r.Decision)
225			pw.stringField(r.PrevFingerprint)
226			pw.stringField(r.Fingerprint)
227		}
228		if pw.err != nil {
229			return nil, pw.err
230		}
231		payload := pw.buf
232	
233		out := make([]byte, 0, len(archiveMagic)+4+len(payload)+sha256.Size)
234		out = append(out, archiveMagic...)
235		var lenBuf [4]byte
236		binary.BigEndian.PutUint32(lenBuf[:], uint32(len(payload)))
237		out = append(out, lenBuf[:]...)
238		out = append(out, payload...)
239		sum := sha256.Sum256(payload)
240		out = append(out, sum[:]...)
241		return out, nil
242	}
243	
244	// archiveReader walks one payload without copying string contents: string
245	// fields are backed by the payload slice itself, which is owned by the
246	// decoder and never returned, so callers cannot mutate the input through
247	// the result.
248	type archiveReader struct {
249		data []byte
250		pos  int
251		err  error
252	}
253	
254	func (r *archiveReader) need(n int) bool {
255		if r.err != nil {
256			return false
257		}
258		if n < 0 || r.pos > len(r.data)-n {
259			r.err = fmt.Errorf("%w: truncated archive payload", ErrInvalidArchive)
260			return false
261		}
262		return true
263	}
264	
265	func (r *archiveReader) marker() byte {
266		if !r.need(1) {
267			return 0
268		}
269		b := r.data[r.pos]
270		r.pos++
271		return b
272	}
273	
274	func (r *archiveReader) u32() int {
275		if !r.need(4) {
276			return 0
277		}
278		v := int(binary.BigEndian.Uint32(r.data[r.pos : r.pos+4]))
279		r.pos += 4
280		return v
281	}
282	
283	// boundedCount reads a count and proves at least minBytesPerItem bytes
284	// remain per item, so a hostile payload cannot drive a huge allocation
285	// with a count its body could never satisfy.
286	func (r *archiveReader) boundedCount(minBytesPerItem int) int {
287		n := r.u32()
288		if r.err != nil {
289			return 0
290		}
291		if n < 0 || uint64(n)*uint64(minBytesPerItem) > uint64(len(r.data)-r.pos) {
292			r.err = fmt.Errorf("%w: implausible list count %d", ErrInvalidArchive, n)
293			return 0
294		}
295		return n
296	}
297	
298	func (r *archiveReader) boolean() bool {
299		switch r.marker() {
300		case archiveTagBoolTrue:
301			return true
302		case archiveTagBoolFalse:
303			return false
304		default:
305			if r.err == nil {
306				r.err = fmt.Errorf("%w: invalid boolean marker", ErrInvalidArchive)
307			}
308			return false
309		}
310	}
311	
312	func (r *archiveReader) stringField() string {
313		n := r.u32()
314		if r.err != nil {
315			return ""
316		}
317		if !r.need(n) {
318			return ""
319		}
320		// Conversion copies the bytes, so the result never aliases the input.
321		s := string(r.data[r.pos : r.pos+n])
322		r.pos += n
323		return s
324	}
325	
326	func (r *archiveReader) stringList() []string {
327		switch r.marker() {
328		case archiveTagNil:
329			return nil
330		case archiveTagPresent:
331		default:
332			if r.err == nil {
333				r.err = fmt.Errorf("%w: invalid list marker", ErrInvalidArchive)
334			}
335			return nil
336		}
337		n := r.boundedCount(4) // each item carries at least one length word
338		if r.err != nil {
339			return nil
340		}
341		items := make([]string, n)
342		for i := range items {
343			items[i] = r.stringField()
344		}
345		return items
346	}
347	
348	func (r *archiveReader) policy() Policy {
349		// Read fields in the single table's (write and fingerprint) order. The
350		// fingerprint-optional ResourceID is still a mandatory, fixed field on
351		// the archive, so it is read for every policy including the empty one.
352		var p Policy
353		for i := range policyFields {
354			f := &policyFields[i]
355			switch f.kind {
356			case policyFieldString, policyFieldOptionalString:
357				f.setString(&p, r.stringField())
358			case policyFieldBool:
359				f.setBool(&p, r.boolean())
360			}
361		}
362		return p
363	}
364	
365	func (r *archiveReader) policyList() []Policy {
366		switch r.marker() {
367		case archiveTagNil:
368			return nil
369		case archiveTagPresent:
370		default:
371			if r.err == nil {
372				r.err = fmt.Errorf("%w: invalid policy list marker", ErrInvalidArchive)
373			}
374			return nil
375		}
376		// A policy writes six length words (five strings plus ResourceID) and
377		// one bool byte at minimum.
378		n := r.boundedCount(6*4 + 1)
379		if r.err != nil {
380			return nil
381		}
382		policies := make([]Policy, n)
383		for i := range policies {
384			policies[i] = r.policy()
385		}
386		return policies
387	}
388	
389	func (r *archiveReader) change() *PolicyChange {
390		switch r.marker() {
391		case archiveTagNil:
392			return nil
393		case archiveTagPresent:
394		default:
395			if r.err == nil {
396				r.err = fmt.Errorf("%w: invalid change payload marker", ErrInvalidArchive)
397			}
398			return nil
399		}
400		c := &PolicyChange{}
401		c.Version = r.u32()
402		c.Policies = r.policyList()
403		c.SourceVersion = r.u32()
404		c.RolledBack = r.boolean()
405		return c
406	}
407	
408	func (r *archiveReader) subject() Subject {
409		var su Subject
410		su.ID = r.stringField()
411		su.Kind = r.stringField()
412		su.Roles = r.stringList()
413		su.Disabled = r.boolean()
414		return su
415	}
416	
417	func (r *archiveReader) resource() Resource {
418		var res Resource
419		res.ID = r.stringField()
420		res.Scope = r.stringField()
421		return res
422	}
423	
424	func (r *archiveReader) decision() Decision {
425		var d Decision
426		d.Allowed = r.boolean()
427		d.Reason = r.stringField()
428		d.Matched = r.stringList()
429		d.Version = r.u32()
430		return d
431	}
432	
433	func (r *archiveReader) decisionRecord() *DecisionRecord {
434		switch r.marker() {
435		case archiveTagNil:
436			return nil
437		case archiveTagPresent:
438		default:
439			if r.err == nil {
440				r.err = fmt.Errorf("%w: invalid decision payload marker", ErrInvalidArchive)
441			}
442			return nil
443		}
444		d := &DecisionRecord{}
445		d.Request.SubjectOrg = r.stringField()
446		d.Request.ResourceOrg = r.stringField()
447		d.Request.Subject = r.subject()
448		d.Request.Resource = r.resource()
449		d.Request.Action = r.stringField()
450		d.Decision = r.decision()
451		return d
452	}
453	
454	// DecodeAuditArchive reads one archive produced by EncodeAuditArchive and
455	// returns records that can be handed directly to RecheckDecisionOffline.
456	// org is the organization the caller expects, and cp is the checkpoint the
457	// caller independently retained; the checkpoint embedded in the file is
458	// never treated as evidence, so even an archive carrying a plausible
459	// checkpoint only validates against the one supplied here.
460	//
461	// A missing organization is ErrMissingOrganization. Unrecognized framing,
462	// truncation, a trailing second archive or any other extra byte, a bad
463	// checksum, and undecodable content are ErrInvalidArchive. Records that
464	// decode but are missing, out of order, foreign to the organization,
465	// modified (including a record after the one the caller intends to review)
466	// or mismatched with the supplied checkpoint fail the whole read with
467	// ErrInvalidRange. Failure returns no records. A successful read only
468	// proves the material matches the checkpoint: an original decision that
469	// disagrees with a recomputed one is reported later by offline review, not
470	// treated as archive damage. The result is detached from archive (mutating
471	// one never reaches the other), and the call is read-only.
472	func DecodeAuditArchive(archive []byte, org string, cp Checkpoint) ([]AuditRecord, error) {
473		if org == "" {
474			return nil, ErrMissingOrganization
475		}
476		magicLen := len(archiveMagic)
477		if len(archive) < magicLen+4+sha256.Size || string(archive[:magicLen]) != archiveMagic {
478			return nil, fmt.Errorf("%w: unrecognized audit archive", ErrInvalidArchive)
479		}
480		pos := magicLen
481		payloadLen := int(binary.BigEndian.Uint32(archive[pos : pos+4]))
482		pos += 4
483		checksumEnd := pos + payloadLen
484		if payloadLen < 0 || checksumEnd+sha256.Size != len(archive) {
485			// A short frame is truncation; bytes beyond the one frame (a
486			// concatenated second archive, junk appended to a good file) are a
487			// framing failure too.
488			return nil, fmt.Errorf("%w: truncated or trailing audit archive bytes", ErrInvalidArchive)
489		}
490		payload := archive[pos:checksumEnd]
491		sum := sha256.Sum256(payload)
492		if !bytes.Equal(sum[:], archive[checksumEnd:checksumEnd+sha256.Size]) {
493			return nil, fmt.Errorf("%w: checksum mismatch", ErrInvalidArchive)
494		}
495	
496		r := &archiveReader{data: payload}
497		embeddedOrg := r.stringField()
498		embeddedEndSeq := r.u32()
499		embeddedFingerprint := r.stringField()
500		// Every record writes two payload markers, a sequence word, two
501		// fingerprint length words and org/kind length words: 22 bytes even
502		// when every string is empty.
503		n := r.boundedCount(22)
504		if r.err != nil {
505			return nil, r.err
506		}
507		records := make([]AuditRecord, 0, n)
508		for i := 0; i < n; i++ {
509			var rec AuditRecord
510			rec.Org = r.stringField()
511			rec.Seq = r.u32()
512			rec.Kind = r.stringField()
513			rec.Change = r.change()
514			rec.Decision = r.decisionRecord()
515			rec.PrevFingerprint = r.stringField()
516			rec.Fingerprint = r.stringField()
517			records = append(records, rec)
518		}
519		if r.err != nil {
520			return nil, r.err
521		}
522		if r.pos != len(payload) {
523			return nil, fmt.Errorf("%w: %d unconsumed archive bytes", ErrInvalidArchive, len(payload)-r.pos)
524		}
525	
526		// Content checks reuse the exact audit-range validation the live export
527		// and offline review paths use, so an archive can never smuggle in a
528		// shape those entry points would reject.
529		if embeddedOrg != org {
530			return nil, fmt.Errorf("%w: archive organization %q does not match %q", ErrInvalidRange, embeddedOrg, org)
531		}
532		// The embedded checkpoint is informational; still, contradicting its own
533		// header means the payload was altered, and the authoritative check
534		// below always uses the caller's independently retained checkpoint.
535		if embeddedEndSeq != cp.EndSeq || embeddedFingerprint != cp.Fingerprint {
536			return nil, fmt.Errorf("%w: embedded checkpoint does not match the retained checkpoint", ErrInvalidRange)
537		}
538		if err := VerifyAudit(org, records, cp); err != nil {
539			return nil, err
540		}
541		return records, nil
542	}
543

