// Package darksafe implements the zero-trust access decision core.
package darksafe

// Subject is an identity that can request access to a resource.
type Subject struct {
	ID       string
	Kind     string // "user", "service", "external"
	Roles    []string
	Disabled bool
}

// Resource is a protected object with a scope path.
type Resource struct {
	ID    string
	Scope string // e.g. "org/payments/ledger"
}

// Decision explains one access evaluation.
type Decision struct {
	Allowed bool
	Reason  string
	Matched []string
	// Version is the policy version actually used, 0 when no published
	// version was evaluated (legacy Access and early rejections).
	Version int
}

// Access evaluates a request and always returns an explanation.
func Access(subject Subject, resource Resource, action string) Decision {
	if subject.Disabled {
		return Decision{Allowed: false, Reason: "subject is disabled"}
	}
	if subject.ID == "" || resource.ID == "" || action == "" {
		return Decision{Allowed: false, Reason: "incomplete request"}
	}
	needed := action + ":" + resource.Scope
	for _, role := range subject.Roles {
		if role == "owner" || role == resource.Scope+":"+action {
			return Decision{Allowed: true, Reason: "role grants " + needed, Matched: []string{role}}
		}
	}
	return Decision{Allowed: false, Reason: "no role grants " + needed}
}

// This file implements organization-scoped policy publishing, rollback,
// and review on top of the decision core. Each organization versions its
// own policy set independently; all state is in-memory and lives until
// the service instance ends.
package darksafe

import (
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
)

// Effect is the outcome a policy produces when it matches a request.
type Effect string

const (
	EffectAllow Effect = "allow"
	EffectDeny  Effect = "deny"
)

// Policy binds one subject and one action to a scope with an effect.
type Policy struct {
	ID        string
	Subject   string
	Action    string
	Scope     string
	Effect    Effect
	Recursive bool // false: only the exact scope; true: the scope and its descendants
	// ResourceID optionally narrows the policy to one exact resource. Empty
	// keeps the legacy scope-only matching. A non-empty value adds a
	// condition on top of subject, action, scope and the organization
	// checks: it never replaces them. Comparison is against the request's
	// raw resource ID, byte for byte: case sensitive, spaces significant,
	// no wildcard or scope-path interpretation, and the resource needs no
	// prior registration.
	//
	// The omitempty tag is load bearing for audit fingerprints: the legacy
	// JSON fingerprint family never had this field, and an empty value must
	// keep serializing to exactly the old bytes.
	ResourceID string `json:",omitempty"`
}

// Sentinel errors so callers can distinguish failure causes with errors.Is.
var (
	// ErrVersionConflict means the caller's expected current version is stale.
	ErrVersionConflict = errors.New("darksafe: version conflict")
